student_code = #{studentCode}, student_name = #{studentName}, phone = #{phone}, password = #{password}, graduation_session = #{graduationSession}, school = #{school}, education = #{education}, study_mode = #{studyMode}, class_id = #{classId}, product_id = #{productId}, join_time = #{joinTime},
